def move_one_ball(arr):
    if not arr:
        return True

    first = arr[0]
    previous = first
    drops = 0

    for current in arr:
        if current < previous:
            drops = drops + 1
        previous = current

    if first < previous:
        drops = drops + 1

    return drops <= 1
